          i += 3;
          col += 3;
          break;
        }
        content += template[i];
        if (template[i] === "\n") {
          line++;
          col = 1;
        } else {
          col++;
        }
        i++;
      }
      if (i > len || (i >= len && !content.endsWith("}}}"))) {
