function renderNodes(nodes: AstNode[], root: unknown, scopes: unknown[]): string {
  let out = "";
  for (const node of nodes) {
    if (node.kind === "text") {
      out += node.value;
    } else if (node.kind === "escaped") {
      const v = resolvePath(node.path, scopes);
      out += escapeHtml(toScalar(v, node.line, node.col));
    } else if (node.kind === "unescaped") {
      const v = resolvePath(node.path, scopes);
      out += toScalar(v, node.line, node.col);
    } else if (node.kind === "if") {
      const v = resolvePath(node.path, scopes);
      if (isTruthy(v)) {
        out += renderNodes(node.then, root, scopes);
      } else {
        out += renderNodes(node.els, root, scopes);
      }
    } else if (node.kind === "each") {
      const v = resolvePath(node.path, scopes);
      if (Array.isArray(v)) {
        if (v.length === 0) {
          out += renderNodes(node.els, root, scopes);
        } else {
          for (let idx = 0; idx < v.length; idx++) {
            out += renderNodes(node.body, root, [v[idx], idx, ...scopes]);
