            throw makeError("Mismatched close: {{/each}} without matching {{#each}}", t.line, t.col);
          } else if (t.type === "if" || t.type === "each") {
            const sub = parseNodes(new Set(["endif", "else", "endeach"]));
            if (inElse) elsNodes.push(...sub);
            else thenNodes.push(...sub);
          } else {
            // text, escaped, unescaped, comment
            if (t.type === "text") {
              if (inElse) elsNodes.push({ kind: "text", value: t.value });
              else thenNodes.push({ kind: "text", value: t.value });
            } else if (t.type === "escaped") {
              if (inElse) elsNodes.push({ kind: "escaped", path: t.path, line: t.line, col: t.col });
              else thenNodes.push({ kind: "escaped", path: t.path, line: t.line, col: t.col });
            } else if (t.type === "unescaped") {
              if (inElse) elsNodes.push({ kind: "unescaped", path: t.path, line: t.line, col: t.col });
              else thenNodes.push({ kind: "unescaped", path: t.path, line: t.line, col: t.col });
