        // If we exited because pos >= tokens.length without finding endif
        if (pos > tokens.length || (pos >= tokens.length && tokens[pos - 1]?.type !== "endif")) {
          // Check if last consumed was endif
        }
        nodes.push({ kind: "if", path: tok.path, line: tok.line, col: tok.col, then: thenNodes, els: elsNodes });
      } else if (tok.type === "each") {
        pos++;
        const bodyNodes: AstNode[] = [];
        const elsNodes: AstNode[] = [];
        let inElse = false;
        let foundElse = false;
        while (pos < tokens.length) {
          const t = tokens[pos];
          if (t.type === "endeach") {
            pos++;
            break;
          } else if (t.type === "else") {
            if (foundElse) {
              throw makeError("Duplicate {{else}}", t.line, t.col);
            }
            foundElse = true;
            inElse = true;
            pos++;
          } else if (t.type === "endif") {
            throw makeError("Mismatched close: {{/if}} without matching {{#if}}", t.line, t.col);
          } else if (t.type === "if" || t.type === "each") {
            const sub = parseNodes(new Set(["endeach", "else", "endif"]));
            if (inElse) elsNodes.push(...sub);
            else bodyNodes.push(...sub);
          } else {
            if (t.type === "text") {
              if (inElse) elsNodes.push({ kind: "text", value: t.value });
              else bodyNodes.push({ kind: "text", value: t.value });
            } else if (t.type === "escaped") {
              if (inElse) elsNodes.push({ kind: "escaped", path: t.path, line: t.line, col: t.col });
              else bodyNodes.push({ kind: "escaped", path: t.path, line: t.line, col: t.col });
            } else if (t.type === "unescaped") {
              if (inElse) elsNodes.push({ kind: "unescaped", path: t.path, line: t.line, col: t.col });
              else bodyNodes.push({ kind: "unescaped", path: t.path, line: t.line, col: t.col });
            } else if (t.type === "comment") {
              // skip
            }
            pos++;
          }
        }
        nodes.push({ kind: "each", path: tok.path, line: tok.line, col: tok.col, body: bodyNodes, els: elsNodes });
      } else if (tok.type === "else") {
        if (stopOn.has("else")) {
