import { render } from "./engine.ts";

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    process.stderr.write("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json\n");
    process.exit(1);
  }

  const [templatePath, dataPath] = args;

  let templateContent: string;
  let dataContent: string;

  try {
    templateContent = await Bun.file(templatePath).text();
  } catch (e) {
    process.stderr.write(`Error reading template file: ${(e as Error).message}\n`);
    process.exit(1);
  }

  try {
    dataContent = await Bun.file(dataPath).text();
  } catch (e) {
    process.stderr.write(`Error reading data file: ${(e as Error).message}\n`);
    process.exit(1);
  }

  let data: unknown;
  try {
    data = JSON.parse(dataContent);
  } catch (e) {
    process.stderr.write(`Error parsing JSON: ${(e as Error).message}\n`);
    process.exit(1);
  }

  let result: string;
  try {
    result = render(templateContent, data);
  } catch (e) {
    process.stderr.write(`Render error: ${(e as Error).message}\n`);
    process.exit(1);
  }

  process.stdout.write(result);
}

main();

import { describe, it, expect } from "bun:test";
import { render } from "../src/engine.ts";

describe("basic interpolation", () => {
  it("escapes HTML in {{}}", () => {
    expect(render("{{x}}", { x: '<a>&\'"' })).toBe("&lt;a&gt;&amp;&#x27;&quot;");
  });

  it("does not escape in {{{}}}", () => {
    expect(render("{{{x}}}", { x: "<b>" })).toBe("<b>");
  });

  it("resolves nested paths", () => {
    expect(render("{{a.b.c}}", { a: { b: { c: 42 } } })).toBe("42");
  });

  it("renders missing values as empty string", () => {
    expect(render("[{{missing}}]", { a: 1 })).toBe("[]");
  });

  it("renders booleans", () => {
    expect(render("{{x}}", { x: true })).toBe("true");
    expect(render("{{x}}", { x: false })).toBe("false");
  });

  it("renders numbers", () => {
    expect(render("{{x}}", { x: 0 })).toBe("0");
    expect(render("{{x}}", { x: 3.14 })).toBe("3.14");
  });

  it("throws on objects", () => {
    expect(() => render("{{x}}", { x: { y: 1 } })).toThrow(/Cannot render object/);
  });

  it("throws on functions", () => {
    expect(() => render("{{x}}", { x: () => 1 })).toThrow(/Cannot render function/);
  });
});

describe("whitespace", () => {
  it("preserves whitespace outside tags", () => {
    expect(render("  hello  {{x}}  world  ", { x: 1 })).toBe("  hello  1  world  ");
  });

  it("preserves newlines", () => {
    expect(render("line1\n{{x}}\nline3", { x: "mid" })).toBe("line1\nmid\nline3");
  });
});

describe("{{#if}}", () => {
  it("renders then branch when truthy", () => {
    expect(render("{{#if x}}yes{{/if}}", { x: true })).toBe("yes");
  });

  it("renders else branch when falsy", () => {
    expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: false })).toBe("no");
  });

  it("supports nesting", () => {
    const tpl = "{{#if a}}A{{#if b}}B{{/if}}{{/if}}";
    expect(render(tpl, { a: true, b: true })).toBe("AB");
    expect(render(tpl, { a: true, b: false })).toBe("A");
    expect(render(tpl, { a: false, b: true })).toBe("");
  });

  it("treats empty array as falsy", () => {
    expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: [] })).toBe("no");
  });

  it("treats non-empty array as truthy", () => {
    expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: [1] })).toBe("yes");
  });

  it("treats zero as falsy", () => {
    expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: 0 })).toBe("no");
  });

  it("treats empty string as falsy", () => {
    expect(render("{{#if x}}yes{{else}}no{{/if}}", { x: "" })).toBe("no");
  });
});

describe("{{#each}}", () => {
  it("iterates arrays", () => {
    expect(render("{{#each items}}{{this}},{{/each}}", { items: ["a", "b", "c"] })).toBe("a,b,c,");
  });

  it("provides @index", () => {
    expect(render("{{#each items}}{{@index}}:{{this}} ", { items: ["x", "y"] })).toBe("0:x 1:y ");
  });

  it("renders else for empty array", () => {
    expect(render("{{#each items}}{{this}}{{else}}empty{{/each}}", { items: [] })).toBe("empty");
  });

  it("supports nested loops", () => {
    const tpl = "{{#each outer}}{{#each inner}}{{this}}{{/each}}|{{/each}}";
    const data = { outer: [{ inner: [1, 2] }, { inner: [3] }] };
    expect(render(tpl, data)).toBe("12|3|");
  });

  it("falls back to root for normal paths", () => {
    const tpl = "{{#each items}}{{this}}-{{root}} {{/each}}";
    expect(render(tpl, { items: [1, 2], root: "R" })).toBe("1-R 2-R ");
  });
});

describe("comments", () => {
  it("emits nothing", () => {
    expect(render("a{{! this is a comment}}b", {})).toBe("ab");
  });
});

describe("error handling", () => {
  it("throws on unclosed {{#if}}", () => {
    expect(() => render("{{#if x}}text", { x: true })).toThrow(/Unclosed.*#if/);
  });

  it("throws on unclosed {{#each}}", () => {
    expect(() => render("{{#each x}}text", { x: [] })).toThrow(/Unclosed.*#each/);
  });

  it("throws on mismatched close", () => {
    expect(() => render("{{#if x}}text{{/each}}", { x: true })).toThrow(/Mismatched close/);
  });

  it("throws on else outside block", () => {
    expect(() => render("text{{else}}", {})).toThrow(/else.*outside/);
  });

  it("throws on duplicate else", () => {
    expect(() => render("{{#if x}}a{{else}}b{{else}}c{{/if}}", { x: true })).toThrow(/Duplicate.*else/);
  });

  it("throws on unknown block", () => {
    expect(() => render("{{#unknown x}}text{{/unknown}}", { x: 1 })).toThrow(/Unknown block/);
  });

  it("throws on endeach without each", () => {
    expect(() => render("{{/each}}", {})).toThrow(/\/each.*without/);
  });

  it("throws on endif without if", () => {
    expect(() => render("{{/if}}", {})).toThrow(/\/if.*without/);
  });

  it("includes line and column in error", () => {
    expect(() => render("{{#if x}}\n{{/each}}", { x: true })).toThrow(/line 2/);
  });

  it("throws on each with non-array", () => {
    expect(() => render("{{#each x}}{{this}}{{/each}}", { x: 42 })).toThrow(/requires an array/);
  });

  it("throws on unclosed triple mustache", () => {
    expect(() => render("{{{x}}", { x: 1 })).toThrow(/Unclosed triple/);
  });
});

describe("integration", () => {
  it("renders a complex template", () => {
    const tpl = [
      "<ul>",
      "{{#each users}}",
      "  <li>{{this.name}} ({{this.role}})</li>",
      "{{/each}}",
      "</ul>",
    ].join("\n");
    const data = {
      users: [
        { name: "<Alice>", role: "admin" },
        { name: "Bob", role: "user" },
      ],
    };
    const expected = [
      "<ul>",
      "  <li>&lt;Alice&gt; (admin)</li>",
      "  <li>Bob (user)</li>",
      "</ul>",
    ].join("\n");
    expect(render(tpl, data)).toBe(expected);
  });
});

