      const startLine = line;
      const startCol = col;
      while (i < len) {
        if (template[i] === "{" && template[i + 1] === "{") break;
        text += template[i];
        if (template[i] === "\n") {
          line++;
          col = 1;
        } else {
          col++;
        }
        i++;
      }
