  | { type: "text"; value: string; line: number; col: number }
  | { type: "escaped"; path: string; line: number; col: number }
  | { type: "unescaped"; path: string; line: number; col: number }
  | { type: "comment"; line: number; col: number }
  | { type: "if"; path: string; line: number; col: number }
  | { type: "else"; line: number; col: number }
  | { type: "endif"; line: number; col: number }
  | { type: "each"; path: string; line: number; col: number }
  | { type: "endeach"; line: number; col: number };

interface ParseError extends Error {
  line: number;
  col: number;
}

function makeError(msg: string, line: number, col: number): ParseError {
  const e = new Error(`${msg} at line ${line}, column ${col}`) as ParseError;
  e.line = line;
  e.col = col;
  return e;
}

function tokenize(template: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let col = 1;
  const len = template.length;

  while (i < len) {
    if (template[i] === "{" && template[i + 1] === "{" && template[i + 2] === "{") {
      const startLine = line;
      const startCol = col;
      i += 3;
      col += 3;
      let content = "";
      let closed = false;
      while (i < len) {
        if (template[i] === "}" && template[i + 1] === "}" && template[i + 2] === "}") {
          i += 3;
          col += 3;
          closed = true;
          break;
        }
        content += template[i];
        if (template[i] === "\n") {
          line++;
          col = 1;
        } else {
          col++;
        }
        i++;
      }
      if (!closed) {
        throw makeError("Unclosed triple-mustache tag", startLine, startCol);
      }
      tokens.push({ type: "unescaped", path: content.trim(), line: startLine, col: startCol });
    } else if (template[i] === "{" && template[i + 1] === "{") {
      const startLine = line;
      const startCol = col;
      i += 2;
      col += 2;
      let content = "";
      let closed = false;
      while (i < len) {
        if (template[i] === "}" && template[i + 1] === "}") {
          i += 2;
          col += 2;
          closed = true;
          break;
        }
        content += template[i];
        if (template[i] === "\n") {
          line++;
          col = 1;
        } else {
          col++;
        }
        i++;
      }
      if (!closed) {
        throw makeError("Unclosed mustache tag", startLine, startCol);
      }
      const trimmed = content.trim();

      if (trimmed.startsWith("!")) {
        tokens.push({ type: "comment", line: startLine, col: startCol });
      } else if (/^#if\b/.test(trimmed)) {
        const path = trimmed.slice(3).trim();
        if (!path) throw makeError("#if requires a path", startLine, startCol);
        tokens.push({ type: "if", path, line: startLine, col: startCol });
      } else if (/^#each\b/.test(trimmed)) {
        const path = trimmed.slice(5).trim();
        if (!path) throw makeError("#each requires a path", startLine, startCol);
        tokens.push({ type: "each", path, line: startLine, col: startCol });
      } else if (trimmed === "else") {
        tokens.push({ type: "else", line: startLine, col: startCol });
      } else if (trimmed === "/if") {
        tokens.push({ type: "endif", line: startLine, col: startCol });
      } else if (trimmed === "/each") {
        tokens.push({ type: "endeach", line: startLine, col: startCol });
      } else if (trimmed.startsWith("#") || trimmed.startsWith("/")) {
        throw makeError(`Unknown block tag: ${trimmed}`, startLine, startCol);
      } else {
        tokens.push({ type: "escaped", path: trimmed, line: startLine, col: startCol });
      }
    } else {
      let text = "";
      const startLine = line;
      const startCol = col;
      while (i < len) {
        if (template[i] === "{" && template[i + 1] === "{") break;
        text += template[i];
        if (template[i] === "\n") {
          line++;
          col = 1;
        } else {
          col++;
        }
        i++;
      }
      tokens.push({ type: "text", value: text, line: startLine, col: startCol });
    }
  }

  return tokens;
}

type AstNode =
  | { kind: "text"; value: string }
  | { kind: "escaped"; path: string; line: number; col: number }
  | { kind: "unescaped"; path: string; line: number; col: number }
  | { kind: "if"; path: string; line: number; col: number; then: AstNode[]; els: AstNode[] }
  | { kind: "each"; path: string; line: number; col: number; body: AstNode[]; els: AstNode[] };

function parse(tokens: Token[]): AstNode[] {
  let pos = 0;

  function parseNodes(stopOn: Set<string>): AstNode[] {
    const nodes: AstNode[] = [];
    while (pos < tokens.length) {
      const tok = tokens[pos];
      if (stopOn.has(tok.type)) return nodes;

      if (tok.type === "text") {
        nodes.push({ kind: "text", value: tok.value });
        pos++;
      } else if (tok.type === "escaped") {
        nodes.push({ kind: "escaped", path: tok.path, line: tok.line, col: tok.col });
        pos++;
      } else if (tok.type === "unescaped") {
        nodes.push({ kind: "unescaped", path: tok.path, line: tok.line, col: tok.col });
        pos++;
      } else if (tok.type === "comment") {
        pos++;
      } else if (tok.type === "if") {
        pos++;
        const thenNodes = parseNodes(new Set(["else", "endif", "endeach"]));
        if (pos >= tokens.length) {
          throw makeError("Unclosed {{#if}} block", tok.line, tok.col);
        }
        const stop1 = tokens[pos];
        if (stop1.type === "endeach") {
          throw makeError("Mismatched close: {{/each}} without matching {{#each}}", stop1.line, stop1.col);
        }
        let elsNodes: AstNode[] = [];
        if (stop1.type === "else") {
          pos++;
          elsNodes = parseNodes(new Set(["else", "endif", "endeach"]));
          if (pos >= tokens.length) {
            throw makeError("Unclosed {{#if}} block", tok.line, tok.col);
          }
          const stop2 = tokens[pos];
          if (stop2.type === "else") {
            throw makeError("Duplicate {{else}}", stop2.line, stop2.col);
          }
          if (stop2.type === "endeach") {
            throw makeError("Mismatched close: {{/each}} without matching {{#each}}", stop2.line, stop2.col);
          }
          pos++;
        } else {
          pos++;
        }
        nodes.push({ kind: "if", path: tok.path, line: tok.line, col: tok.col, then: thenNodes, els: elsNodes });
      } else if (tok.type === "each") {
        pos++;
        const bodyNodes = parseNodes(new Set(["else", "endeach", "endif"]));
        if (pos >= tokens.length) {
          throw makeError("Unclosed {{#each}} block", tok.line, tok.col);
        }
        const stop1 = tokens[pos];
        if (stop1.type === "endif") {
          throw makeError("Mismatched close: {{/if}} without matching {{#if}}", stop1.line, stop1.col);
        }
        let elsNodes: AstNode[] = [];
        if (stop1.type === "else") {
          pos++;
          elsNodes = parseNodes(new Set(["else", "endeach", "endif"]));
          if (pos >= tokens.length) {
            throw makeError("Unclosed {{#each}} block", tok.line, tok.col);
          }
          const stop2 = tokens[pos];
          if (stop2.type === "else") {
            throw makeError("Duplicate {{else}}", stop2.line, stop2.col);
          }
          if (stop2.type === "endif") {
            throw makeError("Mismatched close: {{/if}} without matching {{#if}}", stop2.line, stop2.col);
          }
          pos++;
        } else {
          pos++;
        }
        nodes.push({ kind: "each", path: tok.path, line: tok.line, col: tok.col, body: bodyNodes, els: elsNodes });
      } else if (tok.type === "else") {
        throw makeError("{{else}} outside of a block", tok.line, tok.col);
      } else if (tok.type === "endif") {
        throw makeError("{{/if}} without matching {{#if}}", tok.line, tok.col);
      } else if (tok.type === "endeach") {
        throw makeError("{{/each}} without matching {{#each}}", tok.line, tok.col);
      }
    }
    return nodes;
  }

  return parseNodes(new Set());
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

function resolvePath(path: string, scopes: unknown[]): unknown {
  if (path === "this") {
    return scopes[0];
  }
  if (path === "@index") {
    return scopes[1];
  }
  const parts = path.split(".");
  if (parts[0] === "this") {
    let cur: unknown = scopes[0];
    for (let p = 1; p < parts.length; p++) {
      if (cur === null || cur === undefined || typeof cur !== "object") return undefined;
      cur = (cur as Record<string, unknown>)[parts[p]];
      if (cur === undefined) return undefined;
    }
    return cur;
  }
  for (let s = 0; s < scopes.length; s++) {
    let cur: unknown = scopes[s];
    let found = true;
    for (let p = 0; p < parts.length; p++) {
      if (cur === null || cur === undefined || typeof cur !== "object") {
        found = false;
        break;
      }
      cur = (cur as Record<string, unknown>)[parts[p]];
      if (cur === undefined) {
        found = false;
        break;
      }
    }
    if (found) return cur;
  }
  return undefined;
}

function isTruthy(v: unknown): boolean {
  if (v === null || v === undefined) return false;
  if (v === false) return false;
  if (v === 0) return false;
  if (v === "") return false;
  if (Array.isArray(v) && v.length === 0) return false;
  return true;
}

function toScalar(v: unknown, line: number, col: number): string {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  if (typeof v === "number") return String(v);
  if (typeof v === "boolean") return String(v);
  if (typeof v === "object" || typeof v === "function") {
    throw makeError(`Cannot render ${typeof v} as text`, line, col);
  }
  return String(v);
}

function renderNodes(nodes: AstNode[], scopes: unknown[]): string {
  let out = "";
  for (const node of nodes) {
    if (node.kind === "text") {
      out += node.value;
    } else if (node.kind === "escaped") {
      const v = resolvePath(node.path, scopes);
      out += escapeHtml(toScalar(v, node.line, node.col));
    } else if (node.kind === "unescaped") {
      const v = resolvePath(node.path, scopes);
      out += toScalar(v, node.line, node.col);
    } else if (node.kind === "if") {
      const v = resolvePath(node.path, scopes);
      if (isTruthy(v)) {
        out += renderNodes(node.then, scopes);
      } else {
        out += renderNodes(node.els, scopes);
      }
    } else if (node.kind === "each") {
      const v = resolvePath(node.path, scopes);
      if (Array.isArray(v)) {
        if (v.length === 0) {
          out += renderNodes(node.els, scopes);
        } else {
          for (let idx = 0; idx < v.length; idx++) {
            out += renderNodes(node.body, [v[idx], idx, ...scopes]);
          }
        }
      } else if (v === undefined || v === null) {
        out += renderNodes(node.els, scopes);
      } else {
        throw makeError(`{{#each}} requires an array, got ${typeof v}`, node.line, node.col);
      }
    }
  }
  return out;
}

export function render(template: string, data: unknown): string {
  const tokens = tokenize(template);
  const ast = parse(tokens);
  return renderNodes(ast, [data]);
}

